import json, hashlib
from pathlib import Path

target=Path("/Users/steventran/Sonary")
key=hashlib.sha256(str(target.resolve()).encode()).hexdigest()[:12]
root=Path.home()/".do_again/projects"/key
state=root/"state"
outbox=state/"browser_outbox"
uncertain=state/"browser_delivery_uncertain.json"

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

items=[]
if outbox.is_dir():
    for p in sorted(outbox.glob("*.json")):
        items.append({
            "name":p.name,
            "mtime":p.stat().st_mtime,
            "payload":read_json(p),
        })

print(json.dumps({
  "outbox_items":items,
  "uncertain_exists":uncertain.is_file(),
  "uncertain":read_json(uncertain) if uncertain.is_file() else None,
  "browser_status":read_json(state/"browser_status.json"),
},indent=2,sort_keys=True))
print("SONARY_OUTBOX_RECONCILIATION_PREFLIGHT_OK")
